  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ------------------------------------------\n// 1. User Model\n// ------------------------------------------\nmodel User {\n  id            BigInt    @id @default(autoincrement())\n  username      String    @unique @db.VarChar(50)\n  email         String    @unique @db.VarChar(255)\n  passwordHash  String    @map(\"password_hash\") @db.VarChar(255)\n  currentStreak Int       @default(0) @map(\"current_streak\")\n  longestStreak Int       @default(0) @map(\"longest_streak\")\n  lastActiveAt  DateTime? @map(\"last_active_at\")\n  createdAt     DateTime  @default(now()) @map(\"created_at\")\n  updatedAt     DateTime  @updatedAt @map(\"updated_at\")\n\n  // Relationships\n  settings               UserSettings?\n  subjects               Subject[]\n  studySessions          StudySession[]\n  friends1               Friend[]           @relation(\"User1\")\n  friends2               Friend[]           @relation(\"User2\")\n  sentFriendRequests     FriendRequest[]    @relation(\"Sender\")\n  receivedFriendRequests FriendRequest[]    @relation(\"Receiver\")\n  notifications          Notification[]\n  mailLogs               MailLog[]\n  dailySummaries         UserDailySummary[]\n\n  @@map(\"users\")\n}\n\n// ------------------------------------------\n// 2. UserSettings Model (1:1 with User)\n// ------------------------------------------\nmodel UserSettings {\n  userId                      BigInt   @id @map(\"user_id\")\n  dailyStudyGoalSeconds       Int      @default(7200) @map(\"daily_study_goal_seconds\")\n  isEmailNotificationsEnabled Boolean  @default(true) @map(\"is_email_notifications_enabled\")\n  isPushNotificationsEnabled  Boolean  @default(true) @map(\"is_push_notifications_enabled\")\n  theme                       String   @default(\"dark\") @db.VarChar(20)\n  createdAt                   DateTime @default(now()) @map(\"created_at\")\n  updatedAt                   DateTime @updatedAt @map(\"updated_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"user_settings\")\n}\n\n// ------------------------------------------\n// 3. Subject Model\n// ------------------------------------------\nmodel Subject {\n  id        BigInt   @id @default(autoincrement())\n  userId    BigInt   @map(\"user_id\")\n  name      String   @db.VarChar(100)\n  colorCode String   @default(\"#3B82F6\") @map(\"color_code\") @db.Char(7)\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  user           User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  studySessions  StudySession[]\n  dailySummaries UserDailySummary[]\n\n  @@unique([userId, name], name: \"uq_user_subject_name\")\n  @@map(\"subjects\")\n}\n\n// ------------------------------------------\n// 4. StudySession Model\n// ------------------------------------------\nmodel StudySession {\n  id              BigInt        @id @default(autoincrement())\n  userId          BigInt        @map(\"user_id\")\n  subjectId       BigInt        @map(\"subject_id\")\n  startTime       DateTime      @map(\"start_time\")\n  endTime         DateTime?     @map(\"end_time\")\n  durationSeconds Int?          @map(\"duration_seconds\")\n  status          SessionStatus @default(ACTIVE)\n  createdAt       DateTime      @default(now()) @map(\"created_at\")\n  updatedAt       DateTime      @updatedAt @map(\"updated_at\")\n\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  subject Subject @relation(fields: [subjectId], references: [id], onDelete: Restrict)\n\n  @@map(\"study_sessions\")\n}\n\nenum SessionStatus {\n  ACTIVE\n  PAUSED\n  COMPLETED\n}\n\n// ------------------------------------------\n// 5. Friend Model (Junction for self-reference)\n// ------------------------------------------\nmodel Friend {\n  userId1       BigInt   @map(\"user_id_1\")\n  userId2       BigInt   @map(\"user_id_2\")\n  establishedAt DateTime @default(now()) @map(\"established_at\")\n\n  user1 User @relation(\"User1\", fields: [userId1], references: [id], onDelete: Cascade)\n  user2 User @relation(\"User2\", fields: [userId2], references: [id], onDelete: Cascade)\n\n  @@id([userId1, userId2])\n  @@map(\"friends\")\n}\n\n// ------------------------------------------\n// 6. FriendRequest Model\n// ------------------------------------------\nmodel FriendRequest {\n  id         BigInt        @id @default(autoincrement())\n  senderId   BigInt        @map(\"sender_id\")\n  receiverId BigInt        @map(\"receiver_id\")\n  status     RequestStatus @default(PENDING)\n  sentAt     DateTime      @default(now()) @map(\"sent_at\")\n  updatedAt  DateTime      @updatedAt @map(\"updated_at\")\n\n  sender   User @relation(\"Sender\", fields: [senderId], references: [id], onDelete: Cascade)\n  receiver User @relation(\"Receiver\", fields: [receiverId], references: [id], onDelete: Cascade)\n\n  @@unique([senderId, receiverId], name: \"uq_sender_receiver\")\n  @@map(\"friend_requests\")\n}\n\nenum RequestStatus {\n  PENDING\n  ACCEPTED\n  DECLINED\n}\n\n// ------------------------------------------\n// 7. Notification Model\n// ------------------------------------------\nmodel Notification {\n  id        BigInt   @id @default(autoincrement())\n  userId    BigInt   @map(\"user_id\")\n  title     String   @db.VarChar(150)\n  message   String   @db.Text\n  type      String   @db.VarChar(50)\n  isRead    Boolean  @default(false) @map(\"is_read\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"notifications\")\n}\n\n// ------------------------------------------\n// 8. MailLog Model\n// ------------------------------------------\nmodel MailLog {\n  id             BigInt     @id @default(autoincrement())\n  userId         BigInt?    @map(\"user_id\")\n  recipientEmail String     @map(\"recipient_email\") @db.VarChar(255)\n  subject        String     @db.VarChar(255)\n  templateName   String     @map(\"template_name\") @db.VarChar(50)\n  status         MailStatus @default(PENDING)\n  errorMessage   String?    @map(\"error_message\") @db.Text\n  sentAt         DateTime   @default(now()) @map(\"sent_at\")\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@map(\"mail_logs\")\n}\n\nenum MailStatus {\n  SENT\n  FAILED\n  PENDING\n}\n\n// ------------------------------------------\n// 9. UserDailySummary Model (Analytics Roll-up)\n// ------------------------------------------\nmodel UserDailySummary {\n  id                   BigInt   @id @default(autoincrement())\n  userId               BigInt   @map(\"user_id\")\n  subjectId            BigInt   @map(\"subject_id\")\n  studyDate            DateTime @map(\"study_date\") @db.Date\n  totalDurationSeconds Int      @default(0) @map(\"total_duration_seconds\")\n  sessionsCount        Int      @default(0) @map(\"sessions_count\")\n  createdAt            DateTime @default(now()) @map(\"created_at\")\n  updatedAt            DateTime @updatedAt @map(\"updated_at\")\n\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  subject Subject @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, subjectId, studyDate], name: \"uq_user_subject_date\")\n  @@map(\"user_daily_summaries\")\n}\n",
